INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-2-u6-C6','math',1,2,'u6',7,'덧셈과 뺄셈 익히기 — 바른 계산 찾기·고치기·계산 순서(명령어)',ARRAY['2수01-06']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X01','math',1,'u6',ARRAY['M1-2-u6-C1','M1-2-u6-C2']::text[],'낱개를 10개씩 묶음에 더한다 — 21+7 을 91','수 모형으로 낱개 7개가 어느 자리에 놓이는지 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X02','math',1,'u6',ARRAY['M1-2-u6-C2','M1-2-u6-C6']::text[],'세로 셈에서 자리를 맞추지 않는다 — 13+6 에서 6을 묶음 자리 아래에 써 73','「10개씩 묶음 자리·낱개 자리」 이름을 부르며 자리 맞춰 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X03','math',1,'u6',ARRAY['M1-2-u6-C1','M1-2-u6-C3']::text[],'(몇십)±(몇십)에서 0을 빠뜨린다 — 20+40 을 6','묶음 6개가 60임을 수 모형으로 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X04','math',1,'u6',ARRAY['M1-2-u6-C3','M1-2-u6-C5']::text[],'뺄셈의 두 수를 바꾸어 써도 된다고 본다 — 3−26 과 26−3 이 같다','작은 수에서 큰 수를 뺄 수 없음을 딱지 짝 짓기로 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X05','math',1,'u6',ARRAY['M1-2-u6-C3','M1-2-u6-C4','M1-2-u6-C5']::text[],'견주는 이야기·남은 것을 덧셈으로 구한다 — 26장과 3장 「몇 장 더」를 29','하나씩 짝 짓고 남는 것만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X06','math',1,'u6',ARRAY['M1-2-u6-C4']::text[],'빼는 수의 묶음 수와 낱개 수를 바꿔 뺀다 — 34−12 를 34−21 로','12는 10이 1개·낱개 2개, 21은 10이 2개·낱개 1개임을 수 모형으로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X07','math',1,'u6',ARRAY['M1-2-u6-C1','M1-2-u6-C2','M1-2-u6-C4','M1-2-u6-C6']::text[],'한 자리만 계산한다 — 묶음끼리만(46+11 을 50) 또는 낱개끼리만(7)','묶음 답과 낱개 답을 둘 다 그 자리에 쓴 뒤 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X08','math',1,'u6',ARRAY['M1-2-u6-C5']::text[],'「몇 개 더 많은지·적은지」를 덧셈식으로 세운다 / 「모두」를 뺄셈으로','「모두」는 덧셈, 「몇 개 더」는 뺄셈 — 구하려는 것을 문장으로 먼저 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X09','math',1,'u6',ARRAY['M1-2-u6-C6']::text[],'기호를 잘못 보고 덧셈을 뺄셈으로, 뺄셈을 덧셈으로 계산한다 — 59−23 을 82','계산 전에 기호에 ○ 표를 하고 이야기로 바꿔 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u6-X10','math',1,'u6',ARRAY['M1-2-u6-C6']::text[],'계산 결과를 확인하지 않고 그대로 믿는다 — 틀린 팽이 식을 바르다고 본다','어림으로 「20보다 크고 30보다 작다」를 먼저 말한 뒤 계산과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#1','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',1,'mc','auto','공깃돌 21개를 가지고 있었는데 7개를 더 얻었어요. 모두 몇 개인지 구하는 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X01']::text[],false,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"공깃돌 21개를 가지고 있었는데 7개를 더 얻었어요. 모두 몇 개인지 구하는 식은 어느 것인가요?","options":[{"t":"21 + 7","correct":true},{"t":"21 − 7","mis":"M1-2-u6-X05"},{"t":"21 + 70","mis":"M1-2-u6-X01"}],"explanation":["더 얻었으니 모으는 이야기 — 덧셈이에요.","21 + 7 이에요.","7은 낱개 7개라 70이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#2','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',1,'sa','auto','수 모형을 보세요. 21 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"수 모형을 보세요. 21 + 7 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":2,"ones":1},"right":{"tens":0,"ones":7},"op":"+"},"answer":["28"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 2 + 0 = 2, 낱개끼리 더하면 1 + 7 = 8이에요.","그래서 21 + 7 = 28이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#3','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',1,'sa','auto','20 + 40 은 얼마인가요? 10개씩 묶음끼리 더해 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"20 + 40 은 얼마인가요? 10개씩 묶음끼리 더해 숫자로 쓰세요.","answer":["60"],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 10개씩 묶음끼리만 더해요.","묶음 2개 + 묶음 4개 = 묶음 6개라 60이에요.","6이라고만 쓰면 0을 빠뜨린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#4','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',1,'mc','auto','수 모형을 보세요. 30 + 50 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":4,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"수 모형을 보세요. 30 + 50 은 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":3,"ones":0},"right":{"tens":5,"ones":0},"op":"+"},"options":[{"t":"80","correct":true},{"t":"8","mis":"M1-2-u6-X03"},{"t":"35","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["묶음 3개 + 묶음 5개 = 묶음 8개예요.","묶음 8개는 80이에요.","8은 묶음의 수만 쓴 것, 35는 수를 이어 붙인 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#5','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',2,'sa','auto','43 + 5 는 얼마인가요? 10개씩 묶음끼리, 낱개끼리 더해 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u6-C1","difficulty":2,"kind":"sa","stem":"43 + 5 는 얼마인가요? 10개씩 묶음끼리, 낱개끼리 더해 숫자로 쓰세요.","answer":["48"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 4 + 0 = 4, 낱개끼리 더하면 3 + 5 = 8이에요.","그래서 43 + 5 = 48이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#6','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',2,'ox','auto','십 배열판에서는 낱개가 모여 10개씩 묶음이 되는 것이 보입니다.',ARRAY['M1-2-u6-X01']::text[],false,'{"seq":6,"concept":"M1-2-u6-C1","difficulty":2,"kind":"ox","stem":"십 배열판에서는 낱개가 모여 10개씩 묶음이 되는 것이 보입니다.","answer":"O","reason_options":[{"t":"10칸이 다 차면 묶음 하나가 되니까","correct":true},{"t":"십 배열판은 낱개만 보여 주니까","mis":"M1-2-u6-X01"}],"explanation":["십 배열판 한 판이 10칸이에요.","낱개가 10개 모이면 한 판이 꽉 차 묶음 하나가 돼요.","21 + 7 은 낱개 1에 7을 더해 8, 묶음은 그대로 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#7','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',2,'mc','auto','수 모형을 보세요. 34 + 5 는 얼마인가요?',ARRAY['M1-2-u6-X01','M1-2-u6-X07']::text[],true,'{"seq":7,"concept":"M1-2-u6-C1","difficulty":2,"kind":"mc","stem":"수 모형을 보세요. 34 + 5 는 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":3,"ones":4},"right":{"tens":0,"ones":5},"op":"+"},"options":[{"t":"39","correct":true},{"t":"84","mis":"M1-2-u6-X01"},{"t":"30","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["낱개 4에 5를 더하면 9, 묶음은 그대로 3이에요.","그래서 39예요.","84는 5를 묶음에 더한 답, 30은 낱개를 잊은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#8','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C1","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"21 + 7","r":"28"},{"l":"40 + 30","r":"70"},{"l":"52 + 6","r":"58"}],"explanation":["낱개끼리 더하고 묶음은 그대로 둬요.","(몇십)+(몇십)은 묶음끼리 더하고 0을 붙여요.","21 + 7 = 28, 40 + 30 = 70, 52 + 6 = 58 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#9','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',2,'mc','auto','21 + 7 을 계산하기 전에 어림했어요. 바르게 어림한 것은 어느 것인가요?',ARRAY['M1-2-u6-X01','M1-2-u6-X05']::text[],false,'{"seq":9,"concept":"M1-2-u6-C1","difficulty":2,"kind":"mc","stem":"21 + 7 을 계산하기 전에 어림했어요. 바르게 어림한 것은 어느 것인가요?","options":[{"t":"20보다 크고 30보다 조금 작아요","correct":true},{"t":"90쯤이에요","mis":"M1-2-u6-X01"},{"t":"7보다 작아요","mis":"M1-2-u6-X05"}],"explanation":["21에 7을 더하면 21보다 커져요.","낱개 1에 7을 더해도 10이 안 되니 30보다 작아요.","계산 전에 어림하면 엉뚱한 답을 걸러 낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_basic#10','math',1,2,'u6','L02','g1_2_math_u6_L02_basic','lesson_basic','M1-2-u6-C1',3,'error','auto','지우가 21 + 7 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#1','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',2,'sa','auto','수 모형을 보세요. 52 + 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":2,"kind":"sa","stem":"수 모형을 보세요. 52 + 6 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":5,"ones":2},"right":{"tens":0,"ones":6},"op":"+"},"answer":["58"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 5 + 0 = 5, 낱개끼리 더하면 2 + 6 = 8이에요.","그래서 52 + 6 = 58이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#2','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',2,'mc','auto','60 + 30 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":2,"kind":"mc","stem":"60 + 30 은 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M1-2-u6-X03"},{"t":"63","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["묶음 6개 + 묶음 3개 = 묶음 9개예요.","묶음 9개는 90이에요.","9는 0을 빠뜨린 답, 63은 수를 이어 붙인 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#3','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',3,'ox','auto','7에서 21만큼 이어 세는 것보다 21에서 7만큼 이어 세는 것이 빠릅니다.',ARRAY['M1-2-u6-X01']::text[],false,'{"seq":3,"concept":"M1-2-u6-C1","difficulty":3,"kind":"ox","stem":"7에서 21만큼 이어 세는 것보다 21에서 7만큼 이어 세는 것이 빠릅니다.","answer":"O","reason_options":[{"t":"더 큰 수에서 시작하면 세는 횟수가 적으니까","correct":true},{"t":"작은 수부터 세어야 하니까","mis":"M1-2-u6-X01"}],"explanation":["21 + 7 과 7 + 21 은 답이 같아요.","21에서 7번 세면 되지만 7에서는 21번 세야 해요.","큰 수에서 시작하면 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#4','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',3,'sa','auto','73 + 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C1","difficulty":3,"kind":"sa","stem":"73 + 5 는 얼마인가요? 숫자로 쓰세요.","answer":["78"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 7 + 0 = 7, 낱개끼리 더하면 3 + 5 = 8이에요.","그래서 73 + 5 = 78이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#5','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',3,'mc','auto','바르게 계산한 식은 어느 것인가요?',ARRAY['M1-2-u6-X01','M1-2-u6-X03']::text[],true,'{"seq":5,"concept":"M1-2-u6-C1","difficulty":3,"kind":"mc","stem":"바르게 계산한 식은 어느 것인가요?","options":[{"t":"45 + 3 = 48","correct":true},{"t":"45 + 3 = 75","mis":"M1-2-u6-X01"},{"t":"20 + 50 = 7","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"add","kind":"mix","ask":"check"}},"explanation":["45 + 3 은 낱개 5 + 3 = 8, 묶음 4 — 48이에요.","75는 3을 묶음에 더한 답이에요.","20 + 50 은 70이에요 — 0을 빠뜨리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#6','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',3,'error','auto','민수가 40 + 20 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#7','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',3,'match','auto','이야기와 식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C1","difficulty":3,"kind":"match","stem":"이야기와 식을 선으로 이어 보세요.","pairs":[{"l":"공깃돌 21개에 7개를 더 얻었어요","r":"21 + 7"},{"l":"색종이 30장에 40장을 더 샀어요","r":"30 + 40"},{"l":"구슬 64개에 3개를 더 넣었어요","r":"64 + 3"}],"explanation":["더 얻고, 더 사고, 더 넣으면 덧셈이에요.","처음 수에 더한 수를 그대로 써요.","21 + 7 = 28, 30 + 40 = 70, 64 + 3 = 67 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#8','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',4,'sa','auto','□ + 6 = 39 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C1","difficulty":4,"kind":"sa","stem":"□ + 6 = 39 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["33"],"explanation":["39는 묶음 3개와 낱개 9개예요.","낱개 9는 낱개 3에 6을 더한 것 — □는 33이에요.","33 + 6 = 39 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#9','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',4,'mc','auto','합이 80이 되는 식은 어느 것인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X07']::text[],false,'{"seq":9,"concept":"M1-2-u6-C1","difficulty":4,"kind":"mc","stem":"합이 80이 되는 식은 어느 것인가요?","options":[{"t":"50 + 30","correct":true},{"t":"40 + 4","mis":"M1-2-u6-X03"},{"t":"80 + 8","mis":"M1-2-u6-X07"}],"explanation":["50 + 30 = 80 이에요.","40 + 4 = 44 — 4는 낱개예요.","80 + 8 = 88 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L02_challenge#10','math',1,2,'u6','L02','g1_2_math_u6_L02_challenge','lesson_challenge','M1-2-u6-C1',4,'essay','teacher','25 + 4 를 수 모형과 십 배열판, 두 가지 방법으로 구하는 방법을 쓰고 답을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C1","difficulty":4,"kind":"essay","stem":"25 + 4 를 수 모형과 십 배열판, 두 가지 방법으로 구하는 방법을 쓰고 답을 쓰세요.","answer_guide":"① 수 모형: 묶음 2개는 그대로, 낱개 5개에 4개를 더해 9개 → 29 ② 십 배열판: 낱개 5 옆에 4를 그려 9, 판 두 개 → 29 ③ 답 29 — 셋 다 있으면 만점, 답만 쓰면 절반","explanation":["낱개 5개에 4개를 더하면 9개예요.","10개씩 묶음은 그대로 2개 — 29예요.","어느 방법이든 같은 자리끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#1','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',1,'sa','auto','세로 셈을 보세요. 32 + 15 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C2","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 32 + 15 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":32,"bottom":15,"op":"+","ans":null},"answer":["47"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 3 + 1 = 4, 낱개끼리 더하면 2 + 5 = 7이에요.","그래서 32 + 15 = 47이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#2','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',1,'mc','auto','46 + 11 에서 낱개 자리의 두 수를 더하면 얼마인가요?',ARRAY['M1-2-u6-X07']::text[],true,'{"seq":2,"concept":"M1-2-u6-C2","difficulty":1,"kind":"mc","stem":"46 + 11 에서 낱개 자리의 두 수를 더하면 얼마인가요?","asset":{"type":"vert","top":46,"bottom":11,"op":"+","ans":"hide"},"options":[{"t":"7","correct":true},{"t":"5","mis":"M1-2-u6-X07"},{"t":"57","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"ones"}},"explanation":["낱개 자리의 두 수는 6과 1이에요.","6 + 1 = 7 이에요.","5는 묶음 자리를 더한 수, 57은 전체 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#3','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',1,'sa','auto','사방치기에서 바둑돌이 30과 14에 멈췄어요. 두 수의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u6-C2","difficulty":1,"kind":"sa","stem":"사방치기에서 바둑돌이 30과 14에 멈췄어요. 두 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["44"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 3 + 1 = 4, 낱개끼리 더하면 0 + 4 = 4예요.","그래서 30 + 14 = 44예요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#4','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',1,'mc','auto','11에서 10개씩 묶음의 1과 낱개의 1에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M1-2-u6-X02']::text[],false,'{"seq":4,"concept":"M1-2-u6-C2","difficulty":1,"kind":"mc","stem":"11에서 10개씩 묶음의 1과 낱개의 1에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"묶음의 1은 10을 뜻하고 낱개의 1은 1을 뜻해요","correct":true},{"t":"둘 다 똑같은 1이라서 아무 데나 더해도 돼요","mis":"M1-2-u6-X02"},{"t":"묶음의 1은 1을 뜻하고 낱개의 1은 10을 뜻해요","mis":"M1-2-u6-X02"}],"explanation":["묶음 자리의 1은 10개예요.","낱개 자리의 1은 1개예요.","뜻이 다르니 같은 자리끼리 더해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#5','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',2,'sa','auto','수 모형을 보세요. 46 + 11 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u6-C2","difficulty":2,"kind":"sa","stem":"수 모형을 보세요. 46 + 11 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":4,"ones":6},"right":{"tens":1,"ones":1},"op":"+"},"answer":["57"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 4 + 1 = 5, 낱개끼리 더하면 6 + 1 = 7이에요.","그래서 46 + 11 = 57이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#6','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',2,'mc','auto','세로 셈을 보세요. 23 + 45 는 얼마인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X02']::text[],true,'{"seq":6,"concept":"M1-2-u6-C2","difficulty":2,"kind":"mc","stem":"세로 셈을 보세요. 23 + 45 는 얼마인가요?","asset":{"type":"vert","top":23,"bottom":45,"op":"+","ans":null},"options":[{"t":"68","correct":true},{"t":"60","mis":"M1-2-u6-X07"},{"t":"77","mis":"M1-2-u6-X02"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["묶음 2 + 4 = 6, 낱개 3 + 5 = 8 이에요.","그래서 68이에요.","60은 낱개를 잊은 답, 77은 자리를 섞은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#7','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',2,'ox','auto','세로 셈을 쓸 때 10개씩 묶음은 묶음 자리에, 낱개는 낱개 자리에 줄을 맞추어 씁니다.',ARRAY['M1-2-u6-X02']::text[],false,'{"seq":7,"concept":"M1-2-u6-C2","difficulty":2,"kind":"ox","stem":"세로 셈을 쓸 때 10개씩 묶음은 묶음 자리에, 낱개는 낱개 자리에 줄을 맞추어 씁니다.","answer":"O","reason_options":[{"t":"같은 자리끼리 더해야 하니까","correct":true},{"t":"아무 자리에 써도 답은 같으니까","mis":"M1-2-u6-X02"}],"explanation":["자리를 맞춰야 같은 모형끼리 더할 수 있어요.","13 + 6 에서 6을 묶음 자리 아래 쓰면 73이 되어 틀려요.","자리를 맞추면 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#8','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C2","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"32 + 15","r":"47"},{"l":"40 + 27","r":"67"},{"l":"53 + 24","r":"77"}],"explanation":["묶음끼리, 낱개끼리 더해요.","32 + 15 = 47, 40 + 27 = 67 이에요.","53 + 24 = 77 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_basic#9','math',1,2,'u6','L03','g1_2_math_u6_L03_basic','lesson_basic','M1-2-u6-C2',2,'mc','auto','34 + 21 을 명령어로 계산해요. 「10개씩 묶음끼리 더해요」 다음에 할 일은 무엇인가요?',ARRAY['M1-2-u6-X02','M1-2-u6-X01']::text[],false,'{"seq":9,"concept":"M1-2-u6-C2","difficulty":2,"kind":"mc","stem":"34 + 21 을 명령어로 계산해요. 「10개씩 묶음끼리 더해요」 다음에 할 일은 무엇인가요?","options":[{"t":"합을 10개씩 묶음 자리에 써요","correct":true},{"t":"낱개를 묶음에 더해요","mis":"M1-2-u6-X02"},{"t":"34와 21을 이어 붙여 써요","mis":"M1-2-u6-X01"}],"explanation":["묶음 3 + 2 = 5 를 묶음 자리에 써요.","그다음 낱개 4 + 1 = 5 를 낱개 자리에 써요.","더한 다음 바로 그 자리에 써요 — 55."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
