INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#3','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',3,'ox','auto','52 + 16 = 68 입니다.',ARRAY['M1-2-u6-X01']::text[],true,'{"seq":3,"concept":"M1-2-u6-C2","difficulty":3,"kind":"ox","stem":"52 + 16 = 68 입니다.","answer":"O","reason_options":[{"t":"묶음 5 + 1 = 6, 낱개 2 + 6 = 8 이니까","correct":true},{"t":"5 + 1 + 2 + 6 = 14 니까","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["같은 자리끼리 더해요.","묶음 6, 낱개 8 — 68이에요 — 맞아요.","네 숫자를 다 더하면 자리가 섞여 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#4','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',3,'sa','auto','수 모형을 보세요. 62 + 27 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C2","difficulty":3,"kind":"sa","stem":"수 모형을 보세요. 62 + 27 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":6,"ones":2},"right":{"tens":2,"ones":7},"op":"+"},"answer":["89"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 6 + 2 = 8, 낱개끼리 더하면 2 + 7 = 9예요.","그래서 62 + 27 = 89예요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#5','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',3,'mc','auto','바르게 계산한 식은 어느 것인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X02']::text[],true,'{"seq":5,"concept":"M1-2-u6-C2","difficulty":3,"kind":"mc","stem":"바르게 계산한 식은 어느 것인가요?","options":[{"t":"32 + 14 = 46","correct":true},{"t":"32 + 14 = 40","mis":"M1-2-u6-X07"},{"t":"32 + 14 = 73","mis":"M1-2-u6-X02"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"check"}},"explanation":["묶음 3 + 1 = 4, 낱개 2 + 4 = 6 — 46이에요.","40은 낱개를 잊은 답이에요.","73은 자리를 섞은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
