INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#7','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',3,'match','auto','세로 셈의 자리와 계산을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C2","difficulty":3,"kind":"match","stem":"세로 셈의 자리와 계산을 선으로 이어 보세요.","pairs":[{"l":"46 + 11 의 묶음 자리","r":"4 + 1 = 5"},{"l":"46 + 11 의 낱개 자리","r":"6 + 1 = 7"},{"l":"46 + 11 의 답","r":"57"}],"explanation":["묶음 자리끼리, 낱개 자리끼리 더해요.","묶음 5, 낱개 7이에요.","두 자리를 합쳐 읽으면 57이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#8','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',4,'sa','auto','□ + 23 = 58 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C2","difficulty":4,"kind":"sa","stem":"□ + 23 = 58 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["35"],"explanation":["58은 묶음 5, 낱개 8이에요.","묶음 5 − 2 = 3, 낱개 8 − 3 = 5 — □는 35예요.","35 + 23 = 58 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#9','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',4,'mc','auto','사방치기 판의 수 34, 43, 22, 4, 20, 13 가운데 두 수를 골라 더해 합이 54가 되게 하려면 어느 두 수인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X01']::text[],false,'{"seq":9,"concept":"M1-2-u6-C2","difficulty":4,"kind":"mc","stem":"사방치기 판의 수 34, 43, 22, 4, 20, 13 가운데 두 수를 골라 더해 합이 54가 되게 하려면 어느 두 수인가요?","options":[{"t":"34와 20","correct":true},{"t":"43과 13","mis":"M1-2-u6-X07"},{"t":"22와 4","mis":"M1-2-u6-X01"}],"explanation":["34 + 20 = 54 예요.","43 + 13 = 56, 22 + 4 = 26 이에요.","묶음끼리, 낱개끼리 더해 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L03_challenge#10','math',1,2,'u6','L03','g1_2_math_u6_L03_challenge','lesson_challenge','M1-2-u6-C2',4,'essay','teacher','46 + 11 을 세로 셈으로 쓰고, 왜 같은 모형끼리 더해야 하는지 11의 두 1을 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C2","difficulty":4,"kind":"essay","stem":"46 + 11 을 세로 셈으로 쓰고, 왜 같은 모형끼리 더해야 하는지 11의 두 1을 들어 설명하세요.","answer_guide":"① 세로 셈(자리 맞춤) 46 + 11 = 57 ② 11의 묶음 1은 10, 낱개 1은 1 ③ 뜻이 다르므로 같은 자리끼리 — 셋 다 있으면 만점, 답만 쓰면 절반","explanation":["묶음 4 + 1 = 5, 낱개 6 + 1 = 7 — 57이에요.","11의 묶음 1은 10을, 낱개 1은 1을 뜻해요.","뜻이 다르니 같은 자리끼리만 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#1','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',1,'mc','auto','파란 딱지 26장, 빨간 딱지 3장이에요. 파란 딱지가 빨간 딱지보다 몇 장 더 많은지 구하는 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X04']::text[],false,'{"seq":1,"concept":"M1-2-u6-C3","difficulty":1,"kind":"mc","stem":"파란 딱지 26장, 빨간 딱지 3장이에요. 파란 딱지가 빨간 딱지보다 몇 장 더 많은지 구하는 식은 어느 것인가요?","options":[{"t":"26 − 3","correct":true},{"t":"26 + 3","mis":"M1-2-u6-X05"},{"t":"3 − 26","mis":"M1-2-u6-X04"}],"explanation":["「몇 장 더 많은지」는 견주는 이야기 — 뺄셈이에요.","큰 수 26에서 작은 수 3을 빼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#2','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',1,'sa','auto','그림을 보세요. 파란 딱지는 빨간 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C3","difficulty":1,"kind":"sa","stem":"그림을 보세요. 파란 딱지는 빨간 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.","asset":{"type":"compare_groups","rows":[{"label":"파란 딱지","item":"🟦","n":26},{"label":"빨간 딱지","item":"🟥","n":3}]},"answer":["23"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"story"}},"explanation":["하나씩 짝 지으면 파란 딱지 23장이 남아요.","26 − 3 = 23 이에요.","낱개 6에서 3을 빼고 묶음은 그대로 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#3','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',1,'sa','auto','50 − 20 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u6-C3","difficulty":1,"kind":"sa","stem":"50 − 20 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.","answer":["30"],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 빼요.","묶음 5개에서 2개를 빼면 묶음 3개 → 30이에요.","3이라고만 쓰면 0을 빠뜨린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#4','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',1,'mc','auto','수 모형을 보세요. 47 − 5 는 얼마인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X07']::text[],true,'{"seq":4,"concept":"M1-2-u6-C3","difficulty":1,"kind":"mc","stem":"수 모형을 보세요. 47 − 5 는 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":4,"ones":7},"right":{"tens":0,"ones":5},"op":"-"},"options":[{"t":"42","correct":true},{"t":"52","mis":"M1-2-u6-X05"},{"t":"40","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["낱개 7에서 5를 빼면 2, 묶음은 그대로 4예요.","그래서 42예요.","52는 더한 답, 40은 낱개를 잊은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#5','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',2,'sa','auto','38 − 6 은 얼마인가요? 낱개끼리 빼서 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u6-C3","difficulty":2,"kind":"sa","stem":"38 − 6 은 얼마인가요? 낱개끼리 빼서 숫자로 쓰세요.","answer":["32"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 3 − 0 = 3, 낱개끼리 빼면 8 − 6 = 2예요.","그래서 38 − 6 = 32예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#6','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',2,'ox','auto','26 − 3 과 3 − 26 은 답이 같습니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":6,"concept":"M1-2-u6-C3","difficulty":2,"kind":"ox","stem":"26 − 3 과 3 − 26 은 답이 같습니다.","answer":"X","reason_options":[{"t":"뺄셈은 큰 수에서 작은 수를 빼야 하니까","correct":true},{"t":"두 수만 같으면 되니까","mis":"M1-2-u6-X04"}],"explanation":["3장에서 26장을 뺄 수는 없어요.","견주는 뺄셈은 큰 수에서 작은 수를 빼요.","26 − 3 = 23 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#7','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',2,'mc','auto','그림을 보세요. 노란 딱지는 초록 딱지보다 몇 장 더 많은가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X07']::text[],true,'{"seq":7,"concept":"M1-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림을 보세요. 노란 딱지는 초록 딱지보다 몇 장 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"노란 딱지","item":"🟨","n":15},{"label":"초록 딱지","item":"🟩","n":3}]},"options":[{"t":"12","correct":true},{"t":"18","mis":"M1-2-u6-X05"},{"t":"10","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"story"}},"explanation":["하나씩 짝 지으면 노란 딱지 12장이 남아요.","15 − 3 = 12 예요.","18은 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#8','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C3","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"26 − 3","r":"23"},{"l":"70 − 40","r":"30"},{"l":"59 − 7","r":"52"}],"explanation":["낱개끼리 빼고 묶음은 그대로 둬요.","(몇십)−(몇십)은 묶음끼리 빼고 0을 붙여요.","26 − 3 = 23, 70 − 40 = 30, 59 − 7 = 52 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#9','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',2,'mc','auto','26 − 3 을 계산하기 전에 어림했어요. 바르게 어림한 것은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X04']::text[],false,'{"seq":9,"concept":"M1-2-u6-C3","difficulty":2,"kind":"mc","stem":"26 − 3 을 계산하기 전에 어림했어요. 바르게 어림한 것은 어느 것인가요?","options":[{"t":"26보다 조금 작아요","correct":true},{"t":"26보다 커요","mis":"M1-2-u6-X05"},{"t":"3보다 작아요","mis":"M1-2-u6-X04"}],"explanation":["빼면 처음 수보다 작아져요.","3만 빼니 26보다 조금 작아요.","어림하면 더하는 이야기가 아님을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_basic#10','math',1,2,'u6','L04','g1_2_math_u6_L04_basic','lesson_basic','M1-2-u6-C3',3,'error','auto','지우가 「파란 딱지 26장은 빨간 딱지 3장보다 몇 장 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#1','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',2,'sa','auto','수 모형을 보세요. 68 − 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C3","difficulty":2,"kind":"sa","stem":"수 모형을 보세요. 68 − 5 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":6,"ones":8},"right":{"tens":0,"ones":5},"op":"-"},"answer":["63"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 6 − 0 = 6, 낱개끼리 빼면 8 − 5 = 3이에요.","그래서 68 − 5 = 63이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
