INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#3','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',3,'ox','auto','뺀 결과는 처음 수보다 작아집니다.',ARRAY['M1-2-u6-X05']::text[],false,'{"seq":3,"concept":"M1-2-u6-C3","difficulty":3,"kind":"ox","stem":"뺀 결과는 처음 수보다 작아집니다.","answer":"O","reason_options":[{"t":"덜어 내면 남는 것이 줄어드니까","correct":true},{"t":"빼도 수는 그대로니까","mis":"M1-2-u6-X05"}],"explanation":["26 − 3 = 23 — 26보다 작아요.","덜어 내면 남는 것이 줄어요.","답이 처음 수보다 크면 잘못 계산한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#4','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',3,'sa','auto','그림을 보세요. 빨간 구슬은 파란 구슬보다 몇 개 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C3","difficulty":3,"kind":"sa","stem":"그림을 보세요. 빨간 구슬은 파란 구슬보다 몇 개 더 많은가요? 숫자로 쓰세요.","asset":{"type":"compare_groups","rows":[{"label":"빨간 구슬","item":"🔴","n":18},{"label":"파란 구슬","item":"🔵","n":4}]},"answer":["14"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"story"}},"explanation":["하나씩 짝 지으면 빨간 구슬 14개가 남아요.","18 − 4 = 14 예요.","큰 수에서 작은 수를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#5','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',3,'mc','auto','바르게 계산한 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X03']::text[],true,'{"seq":5,"concept":"M1-2-u6-C3","difficulty":3,"kind":"mc","stem":"바르게 계산한 식은 어느 것인가요?","options":[{"t":"47 − 5 = 42","correct":true},{"t":"47 − 5 = 52","mis":"M1-2-u6-X05"},{"t":"60 − 20 = 4","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"sub","kind":"mix","ask":"check"}},"explanation":["47 − 5 는 낱개 7 − 5 = 2, 묶음 4 — 42예요.","52는 더한 답이에요.","60 − 20 = 40 — 0을 빠뜨리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
