INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#7','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',3,'match','auto','이야기와 식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C3","difficulty":3,"kind":"match","stem":"이야기와 식을 선으로 이어 보세요.","pairs":[{"l":"딱지 26장 가운데 3장을 잃었어요","r":"26 − 3"},{"l":"연필 50자루 가운데 20자루를 나눠 주었어요","r":"50 − 20"},{"l":"사탕 39개는 7개보다 몇 개 더 많나요","r":"39 − 7"}],"explanation":["잃고, 나눠 주고, 견주는 이야기는 뺄셈이에요.","큰 수에서 작은 수를 빼요.","26 − 3 = 23, 50 − 20 = 30, 39 − 7 = 32 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#8','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',4,'sa','auto','□ − 4 = 32 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C3","difficulty":4,"kind":"sa","stem":"□ − 4 = 32 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["36"],"explanation":["32에 뺀 4를 다시 더하면 처음 수예요.","32 + 4 = 36 이에요.","36 − 4 = 32 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#9','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',4,'mc','auto','차가 30이 되는 식은 어느 것인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X03']::text[],false,'{"seq":9,"concept":"M1-2-u6-C3","difficulty":4,"kind":"mc","stem":"차가 30이 되는 식은 어느 것인가요?","options":[{"t":"70 − 40","correct":true},{"t":"38 − 5","mis":"M1-2-u6-X07"},{"t":"30 − 3","mis":"M1-2-u6-X03"}],"explanation":["70 − 40 = 30 이에요.","38 − 5 = 33 이에요.","30 − 3 = 27 — 3은 낱개라 묶음에서 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L04_challenge#10','math',1,2,'u6','L04','g1_2_math_u6_L04_challenge','lesson_challenge','M1-2-u6-C3',4,'essay','teacher','딱지 26장과 3장을 견주어 몇 장 더 많은지 구하는 방법을 짝 짓기와 수 모형, 두 가지로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C3","difficulty":4,"kind":"essay","stem":"딱지 26장과 3장을 견주어 몇 장 더 많은지 구하는 방법을 짝 짓기와 수 모형, 두 가지로 쓰세요.","answer_guide":"① 짝 짓기: 한 장씩 짝 지어 남는 파란 딱지 23장 ② 수 모형: 낱개 6에서 3을 빼 3, 묶음 2 → 23 ③ 답 23 — 셋 다 있으면 만점, 답만 쓰면 절반","explanation":["짝 짓기는 짝 없이 남는 것을 세요.","수 모형은 같은 자리끼리 빼요.","어느 방법이든 26 − 3 = 23 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#1','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',1,'mc','auto','화살 34개를 수 모형으로 놓으면 어떻게 되나요?',ARRAY['M1-2-u6-X06','M1-2-u6-X01']::text[],false,'{"seq":1,"concept":"M1-2-u6-C4","difficulty":1,"kind":"mc","stem":"화살 34개를 수 모형으로 놓으면 어떻게 되나요?","options":[{"t":"10개씩 묶음 3개와 낱개 4개","correct":true},{"t":"10개씩 묶음 4개와 낱개 3개","mis":"M1-2-u6-X06"},{"t":"낱개 34개","mis":"M1-2-u6-X01"}],"explanation":["34는 10개씩 묶음 3개예요.","남은 낱개는 4개예요.","묶음 수와 낱개 수를 바꾸면 43이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#2','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',1,'sa','auto','세로 셈을 보세요. 34 − 12 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C4","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 34 − 12 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":34,"bottom":12,"op":"-","ans":null},"answer":["22"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 3 − 1 = 2, 낱개끼리 빼면 4 − 2 = 2예요.","그래서 34 − 12 = 22예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#3','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',1,'sa','auto','세로 셈을 보세요. 68 − 24 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u6-C4","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 68 − 24 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":68,"bottom":24,"op":"-","ans":null},"answer":["44"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 6 − 2 = 4, 낱개끼리 빼면 8 − 4 = 4예요.","그래서 68 − 24 = 44예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#4','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',1,'mc','auto','34 − 12 에서 10개씩 묶음 자리의 두 수를 빼면 얼마인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X06']::text[],true,'{"seq":4,"concept":"M1-2-u6-C4","difficulty":1,"kind":"mc","stem":"34 − 12 에서 10개씩 묶음 자리의 두 수를 빼면 얼마인가요?","asset":{"type":"vert","top":34,"bottom":12,"op":"-","ans":"hide"},"options":[{"t":"2","correct":true},{"t":"22","mis":"M1-2-u6-X07"},{"t":"4","mis":"M1-2-u6-X06"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"tens"}},"explanation":["묶음 자리의 두 수는 3과 1이에요.","3 − 1 = 2 예요.","22는 전체 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#5','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',2,'sa','auto','수 모형을 보세요. 57 − 21 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u6-C4","difficulty":2,"kind":"sa","stem":"수 모형을 보세요. 57 − 21 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":5,"ones":7},"right":{"tens":2,"ones":1},"op":"-"},"answer":["36"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 5 − 2 = 3, 낱개끼리 빼면 7 − 1 = 6이에요.","그래서 57 − 21 = 36이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#6','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',2,'ox','auto','34 − 12 와 34 − 21 은 답이 같습니다.',ARRAY['M1-2-u6-X06']::text[],false,'{"seq":6,"concept":"M1-2-u6-C4","difficulty":2,"kind":"ox","stem":"34 − 12 와 34 − 21 은 답이 같습니다.","answer":"X","reason_options":[{"t":"12와 21은 묶음 수와 낱개 수가 달라 다른 수니까","correct":true},{"t":"같은 숫자 1과 2로 되어 있으니까","mis":"M1-2-u6-X06"}],"explanation":["12는 묶음 1개·낱개 2개, 21은 묶음 2개·낱개 1개예요.","뜻하는 수가 다르니 34 − 12 = 22, 34 − 21 = 13 으로 달라요.","자리를 바꾸면 다른 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#7','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',2,'mc','auto','세로 셈을 보세요. 49 − 4 는 얼마인가요?',ARRAY['M1-2-u6-X06','M1-2-u6-X05']::text[],true,'{"seq":7,"concept":"M1-2-u6-C4","difficulty":2,"kind":"mc","stem":"세로 셈을 보세요. 49 − 4 는 얼마인가요?","asset":{"type":"vert","top":49,"bottom":4,"op":"-","ans":null},"options":[{"t":"45","correct":true},{"t":"9","mis":"M1-2-u6-X06"},{"t":"53","mis":"M1-2-u6-X05"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["4는 낱개라 낱개 9에서 빼요 — 5.","묶음은 그대로 4 — 45예요.","9는 4를 묶음에서 뺀 답, 53은 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#8','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C4","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"46 − 10","r":"36"},{"l":"33 − 11","r":"22"},{"l":"64 − 13","r":"51"}],"explanation":["묶음끼리, 낱개끼리 빼요.","46 − 10 = 36, 33 − 11 = 22 예요.","64 − 13 = 51 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#9','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',2,'mc','auto','58 − 12 를 명령어로 계산해요. 「10개씩 묶음끼리 빼요 → 차를 묶음 자리에 써요」 다음 두 명령어는 무엇인가요?',ARRAY['M1-2-u6-X06','M1-2-u6-X05']::text[],false,'{"seq":9,"concept":"M1-2-u6-C4","difficulty":2,"kind":"mc","stem":"58 − 12 를 명령어로 계산해요. 「10개씩 묶음끼리 빼요 → 차를 묶음 자리에 써요」 다음 두 명령어는 무엇인가요?","options":[{"t":"낱개끼리 빼요 → 차를 낱개 자리에 써요","correct":true},{"t":"낱개를 묶음에서 빼요 → 그 자리에 써요","mis":"M1-2-u6-X06"},{"t":"두 수를 더해요 → 답을 써요","mis":"M1-2-u6-X05"}],"explanation":["묶음 5 − 1 = 4 를 묶음 자리에 써요.","낱개 8 − 2 = 6 을 낱개 자리에 써요.","58 − 12 = 46 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_basic#10','math',1,2,'u6','L05','g1_2_math_u6_L05_basic','lesson_basic','M1-2-u6-C4',3,'error','auto','지우가 34 − 12 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#1','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',2,'sa','auto','세로 셈을 보세요. 76 − 32 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C4","difficulty":2,"kind":"sa","stem":"세로 셈을 보세요. 76 − 32 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":76,"bottom":32,"op":"-","ans":null},"answer":["44"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 7 − 3 = 4, 낱개끼리 빼면 6 − 2 = 4예요.","그래서 76 − 32 = 44예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#2','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',2,'mc','auto','89 − 45 에서 낱개끼리 빼면 얼마인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C4","difficulty":2,"kind":"mc","stem":"89 − 45 에서 낱개끼리 빼면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"44","mis":"M1-2-u6-X07"},{"t":"14","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"ones"}},"explanation":["낱개 자리의 두 수는 9와 5예요.","9 − 5 = 4 예요.","44는 전체 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#3','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',3,'ox','auto','57 − 21 = 36 입니다.',ARRAY['M1-2-u6-X01']::text[],true,'{"seq":3,"concept":"M1-2-u6-C4","difficulty":3,"kind":"ox","stem":"57 − 21 = 36 입니다.","answer":"O","reason_options":[{"t":"묶음 5 − 2 = 3, 낱개 7 − 1 = 6 이니까","correct":true},{"t":"5 + 2 + 7 + 1 = 15 니까","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["같은 자리끼리 빼요.","묶음 3, 낱개 6 — 36이에요 — 맞아요.","숫자를 다 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#4','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',3,'sa','auto','수 모형을 보세요. 96 − 54 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C4","difficulty":3,"kind":"sa","stem":"수 모형을 보세요. 96 − 54 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":9,"ones":6},"right":{"tens":5,"ones":4},"op":"-"},"answer":["42"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 9 − 5 = 4, 낱개끼리 빼면 6 − 4 = 2예요.","그래서 96 − 54 = 42예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#5','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',3,'mc','auto','바르게 계산한 식은 어느 것인가요?',ARRAY['M1-2-u6-X09','M1-2-u6-X07']::text[],true,'{"seq":5,"concept":"M1-2-u6-C4","difficulty":3,"kind":"mc","stem":"바르게 계산한 식은 어느 것인가요?","options":[{"t":"64 − 13 = 51","correct":true},{"t":"64 − 13 = 77","mis":"M1-2-u6-X09"},{"t":"64 − 13 = 50","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"check"}},"explanation":["묶음 6 − 1 = 5, 낱개 4 − 3 = 1 — 51이에요.","77은 더한 답이에요.","50은 낱개를 잊은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#6','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',3,'error','auto','민수가 34 − 12 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#7','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',3,'match','auto','말판 놀이의 식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C4","difficulty":3,"kind":"match","stem":"말판 놀이의 식과 답을 선으로 이어 보세요.","pairs":[{"l":"29 − 5","r":"24"},{"l":"57 − 21","r":"36"},{"l":"70 − 20","r":"50"}],"explanation":["29 − 5 는 낱개 9 − 5 = 4 — 24예요.","57 − 21 = 36 이에요.","70 − 20 = 50 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#8','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',4,'sa','auto','□ − 23 = 45 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C4","difficulty":4,"kind":"sa","stem":"□ − 23 = 45 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["68"],"explanation":["45에 뺀 23을 다시 더하면 처음 수예요.","45 + 23 = 68 이에요.","68 − 23 = 45 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#9','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',4,'mc','auto','화살 34개 가운데 12개를 던졌어요. 던지지 않은 화살 가운데 10개를 더 던지면 남는 화살은 몇 개인가요?',ARRAY['M1-2-u6-X07','M1-2-u6-X05']::text[],false,'{"seq":9,"concept":"M1-2-u6-C4","difficulty":4,"kind":"mc","stem":"화살 34개 가운데 12개를 던졌어요. 던지지 않은 화살 가운데 10개를 더 던지면 남는 화살은 몇 개인가요?","options":[{"t":"12","correct":true},{"t":"22","mis":"M1-2-u6-X07"},{"t":"32","mis":"M1-2-u6-X05"}],"explanation":["34 − 12 = 22 개가 남아요.","22 − 10 = 12 개예요.","두 번 빼야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L05_challenge#10','math',1,2,'u6','L05','g1_2_math_u6_L05_challenge','lesson_challenge','M1-2-u6-C4',4,'essay','teacher','34 − 12 를 세로 셈으로 쓰고, 12 대신 21을 빼면 답이 왜 달라지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C4","difficulty":4,"kind":"essay","stem":"34 − 12 를 세로 셈으로 쓰고, 12 대신 21을 빼면 답이 왜 달라지는지 쓰세요.","answer_guide":"① 세로 셈 34 − 12 = 22 ② 12는 10이 1개·낱개 2개, 21은 10이 2개·낱개 1개 ③ 뜻하는 수가 달라 34 − 21 = 13 — 셋 다 있으면 만점, 답만 쓰면 절반","explanation":["묶음 3 − 1 = 2, 낱개 4 − 2 = 2 — 22예요.","12와 21은 묶음 수와 낱개 수가 서로 바뀐 다른 수예요.","그래서 답도 달라요 — 34 − 21 = 13."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#1','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',1,'sa','auto','상자에 한과 30개, 바구니에 15개가 있어요. 한과는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C5","difficulty":1,"kind":"sa","stem":"상자에 한과 30개, 바구니에 15개가 있어요. 한과는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["한과","한과"],"ask":"story"}},"explanation":["「모두」는 모으는 이야기 — 덧셈이에요.","30 + 15 = 45 예요.","묶음 3 + 1 = 4, 낱개 0 + 5 = 5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#2','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',1,'sa','auto','꿀떡은 46개, 쑥떡은 24개예요. 꿀떡이 쑥떡보다 몇 개 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C5","difficulty":1,"kind":"sa","stem":"꿀떡은 46개, 쑥떡은 24개예요. 꿀떡이 쑥떡보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["22"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","items":["꿀떡","쑥떡"],"ask":"story"}},"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","46 − 24 = 22 예요.","큰 수에서 작은 수를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#3','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',1,'mc','auto','「꿀떡 35개와 쑥떡 23개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],true,'{"seq":3,"concept":"M1-2-u6-C5","difficulty":1,"kind":"mc","stem":"「꿀떡 35개와 쑥떡 23개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"35 + 23","correct":true},{"t":"35 − 23","mis":"M1-2-u6-X08"},{"t":"23 − 35","mis":"M1-2-u6-X04"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["꿀떡","쑥떡"],"ask":"expr"}},"explanation":["「모두」는 모으는 이야기예요.","모으는 이야기는 덧셈식으로 나타내요.","35 + 23 = 58 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#4','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',1,'match','auto','이야기와 식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u6-C5","difficulty":1,"kind":"match","stem":"이야기와 식을 선으로 이어 보세요.","pairs":[{"l":"한과 상자 20개와 바구니 11개를 모았어요","r":"20 + 11"},{"l":"꿀떡 35개가 쑥떡 23개보다 몇 개 더 많은지","r":"35 − 23"},{"l":"쑥떡 23개가 찹쌀떡 20개보다 몇 개 더 많은지","r":"23 − 20"}],"explanation":["「모두」는 덧셈, 「몇 개 더」는 뺄셈이에요.","견주는 이야기는 큰 수에서 작은 수를 빼요.","20 + 11 = 31, 35 − 23 = 12, 23 − 20 = 3 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#5','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',2,'mc','auto','「쑥떡 23개가 꿀떡 35개보다 몇 개 더 적을까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X04','M1-2-u6-X08']::text[],false,'{"seq":5,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「쑥떡 23개가 꿀떡 35개보다 몇 개 더 적을까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"35 − 23","correct":true},{"t":"23 − 35","mis":"M1-2-u6-X04"},{"t":"35 + 23","mis":"M1-2-u6-X08"}],"explanation":["「몇 개 더 적은지」도 견주는 이야기 — 뺄셈이에요.","큰 수 35에서 작은 수 23을 빼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#6','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',2,'sa','auto','그림을 보세요. 파란 딱지는 빨간 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u6-C5","difficulty":2,"kind":"sa","stem":"그림을 보세요. 파란 딱지는 빨간 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.","asset":{"type":"compare_groups","rows":[{"label":"파란 딱지","item":"🟦","n":26},{"label":"빨간 딱지","item":"🟥","n":12}]},"answer":["14"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"story"}},"explanation":["견주는 이야기는 뺄셈이에요.","26 − 12 = 14 예요.","짝을 못 지은 파란 딱지가 14장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#7','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',2,'ox','auto','「모두 몇 개」를 물으면 덧셈식, 「몇 개 더」를 물으면 뺄셈식으로 나타냅니다.',ARRAY['M1-2-u6-X08']::text[],false,'{"seq":7,"concept":"M1-2-u6-C5","difficulty":2,"kind":"ox","stem":"「모두 몇 개」를 물으면 덧셈식, 「몇 개 더」를 물으면 뺄셈식으로 나타냅니다.","answer":"O","reason_options":[{"t":"모으는 이야기와 견주는 이야기가 다르니까","correct":true},{"t":"무엇을 묻든 큰 수로 계산하니까","mis":"M1-2-u6-X08"}],"explanation":["「모두」는 모으는 이야기 — 덧셈.","「몇 개 더」는 견주는 이야기 — 뺄셈.","구하려는 것을 문장으로 먼저 말하면 식이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_basic#8','math',1,2,'u6','L06','g1_2_math_u6_L06_basic','lesson_basic','M1-2-u6-C5',2,'mc','auto','같은 떡 그림(꿀떡 35개·쑥떡 23개·찹쌀떡 20개)으로 만든 이야기 가운데 뺄셈식이 되는 것은 어느 것인가요?',ARRAY['M1-2-u6-X08']::text[],false,'{"seq":8,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"같은 떡 그림(꿀떡 35개·쑥떡 23개·찹쌀떡 20개)으로 만든 이야기 가운데 뺄셈식이 되는 것은 어느 것인가요?","options":[{"t":"꿀떡이 찹쌀떡보다 몇 개 더 많을까요","correct":true},{"t":"꿀떡과 쑥떡은 모두 몇 개일까요","mis":"M1-2-u6-X08"},{"t":"세 떡을 모으면 몇 개일까요","mis":"M1-2-u6-X08"}],"explanation":["「몇 개 더」는 견주는 이야기 — 뺄셈이에요.","35 − 20 = 15 예요.","「모두」는 덧셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
