INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#4','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',3,'sa','auto','그림을 보세요. 노란 딱지는 초록 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C5","difficulty":3,"kind":"sa","stem":"그림을 보세요. 노란 딱지는 초록 딱지보다 몇 장 더 많은가요? 숫자로 쓰세요.","asset":{"type":"compare_groups","rows":[{"label":"노란 딱지","item":"🟨","n":30},{"label":"초록 딱지","item":"🟩","n":10}]},"answer":["20"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"story"}},"explanation":["견주는 이야기는 뺄셈이에요.","30 − 10 = 20 이에요.","짝을 못 지은 노란 딱지가 20장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#5','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',3,'mc','auto','꿀떡 35개, 쑥떡 23개, 찹쌀떡 20개예요. 「쑥떡과 찹쌀떡은 모두 몇 개일까요?」의 답은 얼마인가요?',ARRAY['M1-2-u6-X08']::text[],false,'{"seq":5,"concept":"M1-2-u6-C5","difficulty":3,"kind":"mc","stem":"꿀떡 35개, 쑥떡 23개, 찹쌀떡 20개예요. 「쑥떡과 찹쌀떡은 모두 몇 개일까요?」의 답은 얼마인가요?","options":[{"t":"43","correct":true},{"t":"3","mis":"M1-2-u6-X08"},{"t":"58","mis":"M1-2-u6-X08"}],"explanation":["쑥떡과 찹쌀떡을 모아요 — 23 + 20.","43이에요.","3은 뺀 답, 58은 꿀떡과 쑥떡을 모은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#6','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',3,'error','auto','민수가 「한과 20개와 11개는 모두 몇 개일까요?」를 이렇게 풀었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#7','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',3,'match','auto','구하려는 것과 식의 종류를 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C5","difficulty":3,"kind":"match","stem":"구하려는 것과 식의 종류를 선으로 이어 보세요.","pairs":[{"l":"모두 몇 개일까요","r":"덧셈식"},{"l":"몇 개 더 많을까요","r":"뺄셈식 (큰 수 − 작은 수)"},{"l":"몇 개 더 적을까요","r":"뺄셈식 (큰 수에서 작은 수를 뺀 것과 같아요)"}],"explanation":["「모두」는 덧셈이에요.","「더 많은지·더 적은지」는 둘 다 견주는 이야기 — 뺄셈이에요.","어느 쪽이든 큰 수에서 작은 수를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#8','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',4,'sa','auto','꿀떡 35개, 쑥떡 23개, 찹쌀떡 20개예요. 꿀떡과 찹쌀떡을 모으면 쑥떡보다 몇 개 더 많은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C5","difficulty":4,"kind":"sa","stem":"꿀떡 35개, 쑥떡 23개, 찹쌀떡 20개예요. 꿀떡과 찹쌀떡을 모으면 쑥떡보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["32"],"explanation":["꿀떡과 찹쌀떡을 모으면 35 + 20 = 55 예요.","55 − 23 = 32 예요.","모은 다음 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#9','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',4,'mc','auto','같은 그림으로 이야기를 만들었어요. 식 「23 − 20」에 맞는 이야기는 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],false,'{"seq":9,"concept":"M1-2-u6-C5","difficulty":4,"kind":"mc","stem":"같은 그림으로 이야기를 만들었어요. 식 「23 − 20」에 맞는 이야기는 어느 것인가요?","options":[{"t":"쑥떡 23개가 찹쌀떡 20개보다 몇 개 더 많을까요","correct":true},{"t":"쑥떡 23개와 찹쌀떡 20개는 모두 몇 개일까요","mis":"M1-2-u6-X08"},{"t":"찹쌀떡 20개가 쑥떡 23개보다 몇 개 더 많을까요","mis":"M1-2-u6-X04"}],"explanation":["23 − 20 은 23과 20을 견주는 식이에요.","큰 수 23이 작은 수 20보다 얼마나 많은지예요.","「모두」는 덧셈이고, 20은 23보다 많지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L06_challenge#10','math',1,2,'u6','L06','g1_2_math_u6_L06_challenge','lesson_challenge','M1-2-u6-C5',4,'essay','teacher','꿀떡 35개·쑥떡 23개 그림으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C5","difficulty":4,"kind":"essay","stem":"꿀떡 35개·쑥떡 23개 그림으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.","answer_guide":"① 덧셈 이야기(모두) + 35 + 23 = 58 ② 뺄셈 이야기(몇 개 더) + 35 − 23 = 12 ③ 「모두」/「몇 개 더」 낱말이 들어 있으면 만점, 식만 쓰면 절반","explanation":["「모두 몇 개」 이야기는 35 + 23 = 58 이에요.","「몇 개 더 많은지」 이야기는 35 − 23 = 12 예요.","같은 그림으로 여러 이야기를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#1','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',1,'mc','auto','팽이 네 개 가운데 바르게 계산한 것은 어느 것인가요?',ARRAY['M1-2-u6-X10']::text[],true,'{"seq":1,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"팽이 네 개 가운데 바르게 계산한 것은 어느 것인가요?","options":[{"t":"20 + 5 = 25","correct":true},{"t":"59 − 23 = 33","mis":"M1-2-u6-X10"},{"t":"32 + 14 = 48","mis":"M1-2-u6-X10"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["20 + 5 = 25 는 맞아요.","59 − 23 = 36, 32 + 14 = 46 이에요.","하나씩 직접 계산해 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#2','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',1,'sa','auto','팽이 「59 − 23 = 33」은 틀렸어요. 59 − 23 의 바른 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C6","difficulty":1,"kind":"sa","stem":"팽이 「59 − 23 = 33」은 틀렸어요. 59 − 23 의 바른 답은 얼마인가요? 숫자로 쓰세요.","answer":["36"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 5 − 2 = 3, 낱개끼리 빼면 9 − 3 = 6이에요.","그래서 59 − 23 = 36이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#3','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',1,'mc','auto','빙고판에서 11과 31을 골라 더했어요(11 + 31 = 42). 무엇을 색칠해야 하나요?',ARRAY['M1-2-u6-X10']::text[],false,'{"seq":3,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"빙고판에서 11과 31을 골라 더했어요(11 + 31 = 42). 무엇을 색칠해야 하나요?","options":[{"t":"고른 두 수 11과 31만","correct":true},{"t":"계산해서 나온 42도 함께","mis":"M1-2-u6-X10"},{"t":"42만","mis":"M1-2-u6-X10"}],"explanation":["빙고는 고른 두 수를 색칠하는 놀이예요.","계산 결과는 색칠하지 않아요.","가로·세로·비스듬히 세 칸이면 빙고!"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#4','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',1,'sa','auto','12 + 40 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C6","difficulty":1,"kind":"sa","stem":"12 + 40 은 얼마인가요? 숫자로 쓰세요.","answer":["52"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 1 + 4 = 5, 낱개끼리 더하면 2 + 0 = 2예요.","그래서 12 + 40 = 52예요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#5','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',2,'sa','auto','뺄셈 빙고에서 89와 32를 골랐어요. 큰 수에서 작은 수를 빼면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"뺄셈 빙고에서 89와 32를 골랐어요. 큰 수에서 작은 수를 빼면 얼마인가요? 숫자로 쓰세요.","answer":["57"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 8 − 3 = 5, 낱개끼리 빼면 9 − 2 = 7이에요.","그래서 89 − 32 = 57이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#6','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',2,'mc','auto','팽이 「30 + 50 = 90」은 틀렸어요. 바르게 고친 것은 어느 것인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X09']::text[],true,'{"seq":6,"concept":"M1-2-u6-C6","difficulty":2,"kind":"mc","stem":"팽이 「30 + 50 = 90」은 틀렸어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"30 + 50 = 80","correct":true},{"t":"30 + 50 = 8","mis":"M1-2-u6-X03"},{"t":"30 + 50 = 20","mis":"M1-2-u6-X09"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"check"}},"explanation":["묶음 3 + 5 = 8 → 80이에요.","8은 0을 빠뜨린 답이에요.","20은 빼기로 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#7','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',2,'ox','auto','뺄셈 빙고에서는 큰 수에서 작은 수를 빼야 합니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":7,"concept":"M1-2-u6-C6","difficulty":2,"kind":"ox","stem":"뺄셈 빙고에서는 큰 수에서 작은 수를 빼야 합니다.","answer":"O","reason_options":[{"t":"작은 수에서 큰 수를 뺄 수 없으니까","correct":true},{"t":"아무 순서로 빼도 같으니까","mis":"M1-2-u6-X04"}],"explanation":["89 − 32 는 되지만 32 − 89 는 안 돼요.","뺄셈은 큰 수에서 작은 수를 빼요.","고른 두 수 가운데 큰 수를 앞에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#8','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',2,'match','auto','틀린 팽이와 바른 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C6","difficulty":2,"kind":"match","stem":"틀린 팽이와 바른 답을 선으로 이어 보세요.","pairs":[{"l":"59 − 23 = 33","r":"36"},{"l":"32 + 14 = 48","r":"46"},{"l":"30 + 50 = 90","r":"80"}],"explanation":["59 − 23 은 묶음 5 − 2 = 3, 낱개 9 − 3 = 6 — 36.","32 + 14 는 46, 30 + 50 은 80이에요.","직접 계산해 견주면 틀린 팽이가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#9','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',2,'mc','auto','덧셈 명령어 「10개씩 묶음끼리 더해요 → 묶음 자리에 써요 → ? → 낱개 자리에 써요」에서 ?에 들어갈 명령어는 무엇인가요?',ARRAY['M1-2-u6-X02','M1-2-u6-X09']::text[],false,'{"seq":9,"concept":"M1-2-u6-C6","difficulty":2,"kind":"mc","stem":"덧셈 명령어 「10개씩 묶음끼리 더해요 → 묶음 자리에 써요 → ? → 낱개 자리에 써요」에서 ?에 들어갈 명령어는 무엇인가요?","options":[{"t":"낱개끼리 더해요","correct":true},{"t":"낱개를 묶음에 더해요","mis":"M1-2-u6-X02"},{"t":"두 수를 빼요","mis":"M1-2-u6-X09"}],"explanation":["묶음을 더해 썼으면 다음은 낱개예요.","낱개끼리 더해 낱개 자리에 써요.","34 + 21 = 55 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_basic#10','math',1,2,'u6','L07','g1_2_math_u6_L07_basic','lesson_basic','M1-2-u6-C6',3,'error','auto','지우가 「64 − 13 = 51」 팽이를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#1','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',2,'mc','auto','바르게 계산한 식은 어느 것인가요?',ARRAY['M1-2-u6-X09','M1-2-u6-X07']::text[],true,'{"seq":1,"concept":"M1-2-u6-C6","difficulty":2,"kind":"mc","stem":"바르게 계산한 식은 어느 것인가요?","options":[{"t":"26 − 10 = 16","correct":true},{"t":"26 − 10 = 36","mis":"M1-2-u6-X09"},{"t":"26 − 10 = 6","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["묶음 2 − 1 = 1, 낱개 6 − 0 = 6 — 16이에요.","36은 더한 답이에요.","6은 낱개만 쓴 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#2','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',2,'sa','auto','덧셈 빙고에서 22와 44를 골랐어요. 두 수의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"덧셈 빙고에서 22와 44를 골랐어요. 두 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["66"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 2 + 4 = 6, 낱개끼리 더하면 2 + 4 = 6이에요.","그래서 22 + 44 = 66이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#3','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',3,'ox','auto','덧셈 명령어에서 낱개끼리 먼저 더하고 묶음끼리 나중에 더해도 답은 같습니다.',ARRAY['M1-2-u6-X02']::text[],false,'{"seq":3,"concept":"M1-2-u6-C6","difficulty":3,"kind":"ox","stem":"덧셈 명령어에서 낱개끼리 먼저 더하고 묶음끼리 나중에 더해도 답은 같습니다.","answer":"O","reason_options":[{"t":"더한 다음 바로 그 자리에 쓰면 어느 쪽을 먼저 해도 되니까","correct":true},{"t":"순서를 바꾸면 자리가 바뀌니까","mis":"M1-2-u6-X02"}],"explanation":["34 + 21 을 낱개부터 해도 55예요.","더한 값을 바로 그 자리에 쓰면 순서는 바꿔도 돼요.","단, 「더해요 → 써요」 순서는 바꿀 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#4','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',3,'sa','auto','뺄셈 빙고에서 78과 45를 골랐어요. 큰 수에서 작은 수를 빼면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C6","difficulty":3,"kind":"sa","stem":"뺄셈 빙고에서 78과 45를 골랐어요. 큰 수에서 작은 수를 빼면 얼마인가요? 숫자로 쓰세요.","answer":["33"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 7 − 4 = 3, 낱개끼리 빼면 8 − 5 = 3이에요.","그래서 78 − 45 = 33이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#5','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',3,'mc','auto','팽이 「50 + 21 = 62」는 틀렸어요. 어떻게 틀렸나요?',ARRAY['M1-2-u6-X10','M1-2-u6-X09']::text[],false,'{"seq":5,"concept":"M1-2-u6-C6","difficulty":3,"kind":"mc","stem":"팽이 「50 + 21 = 62」는 틀렸어요. 어떻게 틀렸나요?","options":[{"t":"낱개 0 + 1 = 1 이라 71이 맞아요","correct":true},{"t":"50 + 21 = 62 는 맞아요","mis":"M1-2-u6-X10"},{"t":"50 − 21 = 29 예요","mis":"M1-2-u6-X09"}],"explanation":["묶음 5 + 2 = 7, 낱개 0 + 1 = 1 — 71이에요.","62는 계산을 확인하지 않은 답이에요.","기호는 더하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#6','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',3,'error','auto','민수가 「12 + 40 = 52」 팽이를 보고 「1 + 4 = 5, 2 + 0 = 2 니까 맞아」라고 하고, 「70 − 40 = 20」 팽이도 맞다고 색칠했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#7','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',3,'match','auto','명령어와 계산을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u6-C6","difficulty":3,"kind":"match","stem":"명령어와 계산을 선으로 이어 보세요.","pairs":[{"l":"10개씩 묶음끼리 빼요 (58 − 12)","r":"5 − 1 = 4"},{"l":"낱개끼리 빼요 (58 − 12)","r":"8 − 2 = 6"},{"l":"답을 읽어요","r":"46"}],"explanation":["묶음 자리는 5 − 1, 낱개 자리는 8 − 2 예요.","묶음 4, 낱개 6이에요.","합쳐 읽으면 46이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#8','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',4,'sa','auto','덧셈 빙고판 11, 12, 22, 23, 31, 33, 43, 44, 55 에서 두 수를 골라 더해 합이 66이 되게 하려고 해요. 22 말고 다른 한 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u6-C6","difficulty":4,"kind":"sa","stem":"덧셈 빙고판 11, 12, 22, 23, 31, 33, 43, 44, 55 에서 두 수를 골라 더해 합이 66이 되게 하려고 해요. 22 말고 다른 한 수는 무엇인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["22 + □ = 66 이에요.","묶음 2 + 4 = 6, 낱개 2 + 4 = 6 — 44예요.","22 + 44 = 66 으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#9','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',4,'mc','auto','뺄셈 빙고판 21, 22, 32, 34, 45, 56, 66, 78, 89 에서 두 수를 골라 뺐더니 차가 33이 되었어요. 어느 두 수인가요?',ARRAY['M1-2-u6-X07']::text[],false,'{"seq":9,"concept":"M1-2-u6-C6","difficulty":4,"kind":"mc","stem":"뺄셈 빙고판 21, 22, 32, 34, 45, 56, 66, 78, 89 에서 두 수를 골라 뺐더니 차가 33이 되었어요. 어느 두 수인가요?","options":[{"t":"78과 45","correct":true},{"t":"56과 22","mis":"M1-2-u6-X07"},{"t":"66과 32","mis":"M1-2-u6-X07"}],"explanation":["78 − 45 = 33 이에요.","56 − 22 = 34, 66 − 32 = 34 예요.","묶음끼리, 낱개끼리 빼 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_L07_challenge#10','math',1,2,'u6','L07','g1_2_math_u6_L07_challenge','lesson_challenge','M1-2-u6-C6',4,'essay','teacher','「59 − 23 = 33」 팽이가 틀린 까닭을 쓰고 바르게 고친 뒤, 계산 전에 어림으로 틀린 것을 알 수 있는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u6-C6","difficulty":4,"kind":"essay","stem":"「59 − 23 = 33」 팽이가 틀린 까닭을 쓰고 바르게 고친 뒤, 계산 전에 어림으로 틀린 것을 알 수 있는 방법을 쓰세요.","answer_guide":"① 낱개 9 − 3 = 6 인데 3으로 써서 틀림 ② 59 − 23 = 36 ③ 어림: 59에서 20쯤 빼면 40에 가까우니 33은 너무 작다 — 셋 다 있으면 만점, 답만 쓰면 절반","explanation":["묶음 5 − 2 = 3, 낱개 9 − 3 = 6 — 36이에요.","낱개 자리를 잘못 계산한 팽이예요.","어림하면 40쯤이라 33은 작다는 것을 미리 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#1','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C1',1,'sa','auto','수 모형을 보세요. 21 + 7 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"수 모형을 보세요. 21 + 7 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":2,"ones":1},"right":{"tens":0,"ones":7},"op":"+"},"answer":["28"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 2 + 0 = 2, 낱개끼리 더하면 1 + 7 = 8이에요.","그래서 21 + 7 = 28이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#2','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C1',1,'mc','auto','20 + 40 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"20 + 40 은 얼마인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M1-2-u6-X03"},{"t":"24","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 더해요.","묶음 2 + 4 = 6 개 → 60이에요.","6은 0을 빠뜨린 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#3','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C1',3,'error','auto','지우가 21 + 7 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#4','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C2',1,'sa','auto','세로 셈을 보세요. 32 + 15 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C2","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 32 + 15 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":32,"bottom":15,"op":"+","ans":null},"answer":["47"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 3 + 1 = 4, 낱개끼리 더하면 2 + 5 = 7이에요.","그래서 32 + 15 = 47이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#5','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C2',2,'mc','auto','46 + 11 에서 낱개 자리의 두 수를 더하면 얼마인가요?',ARRAY['M1-2-u6-X07']::text[],true,'{"seq":5,"concept":"M1-2-u6-C2","difficulty":2,"kind":"mc","stem":"46 + 11 에서 낱개 자리의 두 수를 더하면 얼마인가요?","asset":{"type":"vert","top":46,"bottom":11,"op":"+","ans":"hide"},"options":[{"t":"7","correct":true},{"t":"5","mis":"M1-2-u6-X07"},{"t":"57","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"ones"}},"explanation":["낱개 자리의 두 수는 6과 1이에요.","6 + 1 = 7이에요.","5는 묶음 자리를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
