INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#15','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C5',2,'mc','auto','「꿀떡 35개와 쑥떡 23개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],true,'{"seq":15,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「꿀떡 35개와 쑥떡 23개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"35 + 23","correct":true},{"t":"35 − 23","mis":"M1-2-u6-X08"},{"t":"23 − 35","mis":"M1-2-u6-X04"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["꿀떡","쑥떡"],"ask":"expr"}},"explanation":["「모두」는 모으는 이야기예요.","모으는 이야기는 덧셈식으로 나타내요.","35 + 23 = 58이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#16','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C5',3,'error','auto','하늘이 「꿀떡 46개가 쑥떡 24개보다 몇 개 더 많을까요?」를 이렇게 풀었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#17','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C6',1,'mc','auto','팽이 가운데 바르게 계산한 것은 어느 것인가요?',ARRAY['M1-2-u6-X10']::text[],true,'{"seq":17,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"팽이 가운데 바르게 계산한 것은 어느 것인가요?","options":[{"t":"20 + 5 = 25","correct":true},{"t":"59 − 23 = 33","mis":"M1-2-u6-X10"},{"t":"32 + 14 = 48","mis":"M1-2-u6-X10"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["20 + 5 = 25 는 맞아요.","나머지 둘은 직접 계산하면 답이 달라요.","하나씩 계산해 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#18','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C6',2,'sa','auto','팽이 「59 − 23 = 33」은 틀렸어요. 59 − 23 의 바른 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"팽이 「59 − 23 = 33」은 틀렸어요. 59 − 23 의 바른 답은 얼마인가요? 숫자로 쓰세요.","answer":["36"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 5 − 2 = 3, 낱개끼리 빼면 9 − 3 = 6이에요.","그래서 59 − 23 = 36이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#19','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C6',2,'ox','auto','70 − 40 = 30 입니다.',ARRAY['M1-2-u6-X03']::text[],true,'{"seq":19,"concept":"M1-2-u6-C6","difficulty":2,"kind":"ox","stem":"70 − 40 = 30 입니다.","answer":"O","reason_options":[{"t":"묶음 7 − 4 = 3 이니까","correct":true},{"t":"7 − 4 = 3 이 답이니까","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["묶음 7개에서 4개를 빼면 3개예요.","묶음 3개는 30이에요 — 맞아요.","묶음 수 뒤에 0을 붙여 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#20','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C6',3,'error','auto','지우가 「64 − 13 = 51」 팽이를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#21','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C5',4,'essay','teacher','떡 그림(35개·23개·20개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M1-2-u6-C5","difficulty":4,"kind":"essay","stem":"떡 그림(35개·23개·20개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.","answer_guide":"① 덧셈 이야기(모두) + 식·답(예: 35 + 23 = 58) ② 뺄셈 이야기(몇 개 더) + 식·답(예: 35 − 23 = 12) ③ 「모두」/「몇 개 더」 낱말 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["「모두 몇 개」 이야기는 덧셈 — 35 + 23 = 58.","「몇 개 더」 이야기는 뺄셈 — 35 − 23 = 12.","같은 그림으로 여러 이야기를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#22','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C2',4,'sa','auto','□ + 15 = 47 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M1-2-u6-C2","difficulty":4,"kind":"sa","stem":"□ + 15 = 47 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["32"],"explanation":["47은 묶음 4, 낱개 7이에요.","묶음 4 − 1 = 3, 낱개 7 − 5 = 2 — □는 32예요.","32 + 15 = 47 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#23','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C4',4,'sa','auto','□ − 12 = 22 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M1-2-u6-C4","difficulty":4,"kind":"sa","stem":"□ − 12 = 22 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["34"],"explanation":["22에 뺀 12를 다시 더하면 처음 수예요.","22 + 12 = 34예요.","34 − 12 = 22 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#24','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C3',3,'ox','auto','47 − 5 와 5 − 47 은 답이 같습니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":24,"concept":"M1-2-u6-C3","difficulty":3,"kind":"ox","stem":"47 − 5 와 5 − 47 은 답이 같습니다.","answer":"X","reason_options":[{"t":"뺄셈은 큰 수에서 작은 수를 빼야 하니까","correct":true},{"t":"두 수만 같으면 되니까","mis":"M1-2-u6-X04"}],"explanation":["5에서 47을 뺄 수는 없어요.","견주는 뺄셈은 큰 수에서 작은 수를 빼요.","47 − 5 = 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_a#25','math',1,2,'u6','review','g1_2_math_u6_review_a','unit_review','M1-2-u6-C1',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u6-C1","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"21 + 7","r":"28"},{"l":"20 + 40","r":"60"},{"l":"47 − 5","r":"42"}],"explanation":["낱개끼리 더하거나 빼고 묶음은 그대로 둬요.","(몇십)+(몇십)은 묶음끼리 더하고 0을 붙여요.","같은 자리끼리 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#1','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C1',1,'sa','auto','수 모형을 보세요. 32 + 6 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"수 모형을 보세요. 32 + 6 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":3,"ones":2},"right":{"tens":0,"ones":6},"op":"+"},"answer":["38"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 3 + 0 = 3, 낱개끼리 더하면 2 + 6 = 8이에요.","그래서 32 + 6 = 38이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#2','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C1',1,'mc','auto','30 + 50 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"30 + 50 은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M1-2-u6-X03"},{"t":"35","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 더해요.","묶음 3 + 5 = 8 개 → 80이에요.","8은 0을 빠뜨린 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
