INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#4','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C2',1,'sa','auto','세로 셈을 보세요. 41 + 36 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C2","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 41 + 36 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":41,"bottom":36,"op":"+","ans":null},"answer":["77"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 4 + 3 = 7, 낱개끼리 더하면 1 + 6 = 7이에요.","그래서 41 + 36 = 77이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#5','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C2',2,'mc','auto','52 + 16 에서 낱개 자리의 두 수를 더하면 얼마인가요?',ARRAY['M1-2-u6-X07']::text[],true,'{"seq":5,"concept":"M1-2-u6-C2","difficulty":2,"kind":"mc","stem":"52 + 16 에서 낱개 자리의 두 수를 더하면 얼마인가요?","asset":{"type":"vert","top":52,"bottom":16,"op":"+","ans":"hide"},"options":[{"t":"8","correct":true},{"t":"6","mis":"M1-2-u6-X07"},{"t":"68","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"ones"}},"explanation":["낱개 자리의 두 수는 2와 6이에요.","2 + 6 = 8이에요.","6은 묶음 자리를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
