INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#7','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C3',1,'mc','auto','노란 딱지 28개, 초록 딱지 5개예요. 노란 딱지가 초록 딱지보다 몇 개 더 많은지 구하는 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X04']::text[],false,'{"seq":7,"concept":"M1-2-u6-C3","difficulty":1,"kind":"mc","stem":"노란 딱지 28개, 초록 딱지 5개예요. 노란 딱지가 초록 딱지보다 몇 개 더 많은지 구하는 식은 어느 것인가요?","options":[{"t":"28 − 5","correct":true},{"t":"28 + 5","mis":"M1-2-u6-X05"},{"t":"5 − 28","mis":"M1-2-u6-X04"}],"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","큰 수 28에서 작은 수 5를 빼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#8','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C3',1,'sa','auto','70 − 30 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u6-C3","difficulty":1,"kind":"sa","stem":"70 − 30 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.","answer":["40"],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 빼요.","묶음 7개에서 3개를 빼면 묶음 4개 → 40이에요.","묶음 수 뒤에 0을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#9','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C3',2,'mc','auto','수 모형을 보세요. 58 − 6 은 얼마인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X07']::text[],true,'{"seq":9,"concept":"M1-2-u6-C3","difficulty":2,"kind":"mc","stem":"수 모형을 보세요. 58 − 6 은 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":5,"ones":8},"right":{"tens":0,"ones":6},"op":"-"},"options":[{"t":"52","correct":true},{"t":"64","mis":"M1-2-u6-X05"},{"t":"50","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 5 − 0 = 5, 낱개끼리 빼면 8 − 6 = 2예요.","그래서 58 − 6 = 52예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#10','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C4',1,'sa','auto','세로 셈을 보세요. 57 − 21 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u6-C4","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 57 − 21 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":57,"bottom":21,"op":"-","ans":null},"answer":["36"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 5 − 2 = 3, 낱개끼리 빼면 7 − 1 = 6이에요.","그래서 57 − 21 = 36이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#11','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C4',2,'mc','auto','76 − 32 는 얼마인가요?',ARRAY['M1-2-u6-X06','M1-2-u6-X07']::text[],true,'{"seq":11,"concept":"M1-2-u6-C4","difficulty":2,"kind":"mc","stem":"76 − 32 는 얼마인가요?","options":[{"t":"44","correct":true},{"t":"53","mis":"M1-2-u6-X06"},{"t":"40","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 7 − 3 = 4, 낱개끼리 빼면 6 − 2 = 4예요.","그래서 76 − 32 = 44예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#12','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C4',3,'error','auto','하늘이 57 − 21 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#13','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C5',1,'sa','auto','약과 40개와 약과 25개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u6-C5","difficulty":1,"kind":"sa","stem":"약과 40개와 약과 25개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.","answer":["65"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["약과","약과"],"ask":"story"}},"explanation":["「모두」는 모으는 이야기 — 덧셈이에요.","40 + 25 = 65예요.","묶음끼리, 낱개끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#14','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C5',2,'mc','auto','구슬 58개는 딱지 36개보다 몇 개 더 많은가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X07']::text[],true,'{"seq":14,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"구슬 58개는 딱지 36개보다 몇 개 더 많은가요?","options":[{"t":"22","correct":true},{"t":"94","mis":"M1-2-u6-X08"},{"t":"20","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","items":["구슬","딱지"],"ask":"story"}},"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","58 − 36 = 22예요.","94는 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#15','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C5',2,'mc','auto','「연필 42개와 지우개 31개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],true,'{"seq":15,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「연필 42개와 지우개 31개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"42 + 31","correct":true},{"t":"42 − 31","mis":"M1-2-u6-X08"},{"t":"31 − 42","mis":"M1-2-u6-X04"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["연필","지우개"],"ask":"expr"}},"explanation":["「모두」는 모으는 이야기예요.","모으는 이야기는 덧셈식으로 나타내요.","42 + 31 = 73이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#16','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C5',3,'error','auto','보라가 「구슬 58개가 딱지 36개보다 몇 개 더 많을까요?」를 이렇게 풀었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#17','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C6',1,'mc','auto','팽이 가운데 바르게 계산한 것은 어느 것인가요?',ARRAY['M1-2-u6-X10']::text[],true,'{"seq":17,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"팽이 가운데 바르게 계산한 것은 어느 것인가요?","options":[{"t":"30 + 40 = 70","correct":true},{"t":"48 − 26 = 20","mis":"M1-2-u6-X10"},{"t":"21 + 35 = 65","mis":"M1-2-u6-X10"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["30 + 40 = 70 는 맞아요.","나머지 둘은 직접 계산하면 답이 달라요.","하나씩 계산해 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#18','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C6',2,'sa','auto','팽이 「48 − 26 = 25」은 틀렸어요. 48 − 26 의 바른 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"팽이 「48 − 26 = 25」은 틀렸어요. 48 − 26 의 바른 답은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 4 − 2 = 2, 낱개끼리 빼면 8 − 6 = 2예요.","그래서 48 − 26 = 22예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#19','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C6',2,'ox','auto','90 − 60 = 30 입니다.',ARRAY['M1-2-u6-X03']::text[],true,'{"seq":19,"concept":"M1-2-u6-C6","difficulty":2,"kind":"ox","stem":"90 − 60 = 30 입니다.","answer":"O","reason_options":[{"t":"묶음 9 − 6 = 3 이니까","correct":true},{"t":"9 − 6 = 3 이 답이니까","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["묶음 9개에서 6개를 빼면 3개예요.","묶음 3개는 30이에요 — 맞아요.","묶음 수 뒤에 0을 붙여 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#20','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C6',3,'error','auto','지우가 「52 − 31 = 21」 팽이를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#21','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C5',4,'essay','teacher','떡 그림(42개·31개·20개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M1-2-u6-C5","difficulty":4,"kind":"essay","stem":"떡 그림(42개·31개·20개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.","answer_guide":"① 덧셈 이야기(모두) + 식·답(예: 42 + 31 = 73) ② 뺄셈 이야기(몇 개 더) + 식·답(예: 42 − 31 = 11) ③ 「모두」/「몇 개 더」 낱말 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["「모두 몇 개」 이야기는 덧셈 — 42 + 31 = 73.","「몇 개 더」 이야기는 뺄셈 — 42 − 31 = 11.","같은 그림으로 여러 이야기를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#22','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C2',4,'sa','auto','□ + 36 = 77 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M1-2-u6-C2","difficulty":4,"kind":"sa","stem":"□ + 36 = 77 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["41"],"explanation":["77은 묶음 7, 낱개 7이에요.","묶음 7 − 3 = 4, 낱개 7 − 6 = 1 — □는 41이에요.","41 + 36 = 77 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#23','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C4',4,'sa','auto','□ − 21 = 36 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M1-2-u6-C4","difficulty":4,"kind":"sa","stem":"□ − 21 = 36 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["57"],"explanation":["36에 뺀 21을 다시 더하면 처음 수예요.","36 + 21 = 57이에요.","57 − 21 = 36 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#24','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C3',3,'ox','auto','58 − 6 과 6 − 58 은 답이 같습니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":24,"concept":"M1-2-u6-C3","difficulty":3,"kind":"ox","stem":"58 − 6 과 6 − 58 은 답이 같습니다.","answer":"X","reason_options":[{"t":"뺄셈은 큰 수에서 작은 수를 빼야 하니까","correct":true},{"t":"두 수만 같으면 되니까","mis":"M1-2-u6-X04"}],"explanation":["6에서 58을 뺄 수는 없어요.","견주는 뺄셈은 큰 수에서 작은 수를 빼요.","58 − 6 = 52예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_b#25','math',1,2,'u6','review','g1_2_math_u6_review_b','unit_review','M1-2-u6-C1',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u6-C1","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"32 + 6","r":"38"},{"l":"30 + 50","r":"80"},{"l":"58 − 6","r":"52"}],"explanation":["낱개끼리 더하거나 빼고 묶음은 그대로 둬요.","(몇십)+(몇십)은 묶음끼리 더하고 0을 붙여요.","같은 자리끼리 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#1','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C1',1,'sa','auto','수 모형을 보세요. 43 + 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"수 모형을 보세요. 43 + 5 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":4,"ones":3},"right":{"tens":0,"ones":5},"op":"+"},"answer":["48"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 4 + 0 = 4, 낱개끼리 더하면 3 + 5 = 8이에요.","그래서 43 + 5 = 48이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#2','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C1',1,'mc','auto','10 + 60 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"10 + 60 은 얼마인가요?","options":[{"t":"70","correct":true},{"t":"7","mis":"M1-2-u6-X03"},{"t":"16","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 더해요.","묶음 1 + 6 = 7 개 → 70이에요.","7은 0을 빠뜨린 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
