INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#7','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C3',1,'mc','auto','빨간 구슬 19개, 파란 구슬 4개예요. 빨간 구슬이 파란 구슬보다 몇 개 더 많은지 구하는 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X04']::text[],false,'{"seq":7,"concept":"M1-2-u6-C3","difficulty":1,"kind":"mc","stem":"빨간 구슬 19개, 파란 구슬 4개예요. 빨간 구슬이 파란 구슬보다 몇 개 더 많은지 구하는 식은 어느 것인가요?","options":[{"t":"19 − 4","correct":true},{"t":"19 + 4","mis":"M1-2-u6-X05"},{"t":"4 − 19","mis":"M1-2-u6-X04"}],"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","큰 수 19에서 작은 수 4를 빼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#8','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C3',1,'sa','auto','60 − 40 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u6-C3","difficulty":1,"kind":"sa","stem":"60 − 40 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.","answer":["20"],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 빼요.","묶음 6개에서 4개를 빼면 묶음 2개 → 20이에요.","묶음 수 뒤에 0을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#9','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C3',2,'mc','auto','수 모형을 보세요. 39 − 7 은 얼마인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X07']::text[],true,'{"seq":9,"concept":"M1-2-u6-C3","difficulty":2,"kind":"mc","stem":"수 모형을 보세요. 39 − 7 은 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":3,"ones":9},"right":{"tens":0,"ones":7},"op":"-"},"options":[{"t":"32","correct":true},{"t":"46","mis":"M1-2-u6-X05"},{"t":"30","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 3 − 0 = 3, 낱개끼리 빼면 9 − 7 = 2예요.","그래서 39 − 7 = 32예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#10','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C4',1,'sa','auto','세로 셈을 보세요. 68 − 45 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u6-C4","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 68 − 45 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":68,"bottom":45,"op":"-","ans":null},"answer":["23"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 6 − 4 = 2, 낱개끼리 빼면 8 − 5 = 3이에요.","그래서 68 − 45 = 23이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
