INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#13','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C5',1,'sa','auto','한과 20개와 한과 35개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u6-C5","difficulty":1,"kind":"sa","stem":"한과 20개와 한과 35개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["한과","한과"],"ask":"story"}},"explanation":["「모두」는 모으는 이야기 — 덧셈이에요.","20 + 35 = 55예요.","묶음끼리, 낱개끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
