INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#15','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C5',2,'mc','auto','「공깃돌 54개와 공깃돌 22개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],true,'{"seq":15,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「공깃돌 54개와 공깃돌 22개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"54 + 22","correct":true},{"t":"54 − 22","mis":"M1-2-u6-X08"},{"t":"22 − 54","mis":"M1-2-u6-X04"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["공깃돌","공깃돌"],"ask":"expr"}},"explanation":["「모두」는 모으는 이야기예요.","모으는 이야기는 덧셈식으로 나타내요.","54 + 22 = 76이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
