INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#17','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C6',1,'mc','auto','팽이 가운데 바르게 계산한 것은 어느 것인가요?',ARRAY['M1-2-u6-X10']::text[],true,'{"seq":17,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"팽이 가운데 바르게 계산한 것은 어느 것인가요?","options":[{"t":"26 − 10 = 16","correct":true},{"t":"12 + 40 = 16","mis":"M1-2-u6-X10"},{"t":"50 + 21 = 62","mis":"M1-2-u6-X10"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["26 − 10 = 16 는 맞아요.","나머지 둘은 직접 계산하면 답이 달라요.","하나씩 계산해 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#18','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C6',2,'sa','auto','팽이 「97 − 53 = 41」은 틀렸어요. 97 − 53 의 바른 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"팽이 「97 − 53 = 41」은 틀렸어요. 97 − 53 의 바른 답은 얼마인가요? 숫자로 쓰세요.","answer":["44"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 9 − 5 = 4, 낱개끼리 빼면 7 − 3 = 4예요.","그래서 97 − 53 = 44예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#19','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C6',2,'ox','auto','80 − 50 = 30 입니다.',ARRAY['M1-2-u6-X03']::text[],true,'{"seq":19,"concept":"M1-2-u6-C6","difficulty":2,"kind":"ox","stem":"80 − 50 = 30 입니다.","answer":"O","reason_options":[{"t":"묶음 8 − 5 = 3 이니까","correct":true},{"t":"8 − 5 = 3 이 답이니까","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["묶음 8개에서 5개를 빼면 3개예요.","묶음 3개는 30이에요 — 맞아요.","묶음 수 뒤에 0을 붙여 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#20','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C6',3,'error','auto','지우가 「46 − 32 = 14」 팽이를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#21','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C5',4,'essay','teacher','떡 그림(54개·22개·30개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M1-2-u6-C5","difficulty":4,"kind":"essay","stem":"떡 그림(54개·22개·30개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.","answer_guide":"① 덧셈 이야기(모두) + 식·답(예: 54 + 22 = 76) ② 뺄셈 이야기(몇 개 더) + 식·답(예: 54 − 22 = 32) ③ 「모두」/「몇 개 더」 낱말 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["「모두 몇 개」 이야기는 덧셈 — 54 + 22 = 76.","「몇 개 더」 이야기는 뺄셈 — 54 − 22 = 32.","같은 그림으로 여러 이야기를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#22','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C2',4,'sa','auto','□ + 45 = 68 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M1-2-u6-C2","difficulty":4,"kind":"sa","stem":"□ + 45 = 68 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["23"],"explanation":["68은 묶음 6, 낱개 8이에요.","묶음 6 − 4 = 2, 낱개 8 − 5 = 3 — □는 23이에요.","23 + 45 = 68 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#23','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C4',4,'sa','auto','□ − 45 = 23 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M1-2-u6-C4","difficulty":4,"kind":"sa","stem":"□ − 45 = 23 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["68"],"explanation":["23에 뺀 45를 다시 더하면 처음 수예요.","23 + 45 = 68이에요.","68 − 45 = 23 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#24','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C3',3,'ox','auto','39 − 7 과 7 − 39 는 답이 같습니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":24,"concept":"M1-2-u6-C3","difficulty":3,"kind":"ox","stem":"39 − 7 과 7 − 39 는 답이 같습니다.","answer":"X","reason_options":[{"t":"뺄셈은 큰 수에서 작은 수를 빼야 하니까","correct":true},{"t":"두 수만 같으면 되니까","mis":"M1-2-u6-X04"}],"explanation":["7에서 39를 뺄 수는 없어요.","견주는 뺄셈은 큰 수에서 작은 수를 빼요.","39 − 7 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_c#25','math',1,2,'u6','review','g1_2_math_u6_review_c','unit_review','M1-2-u6-C1',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u6-C1","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"43 + 5","r":"48"},{"l":"10 + 60","r":"70"},{"l":"39 − 7","r":"32"}],"explanation":["낱개끼리 더하거나 빼고 묶음은 그대로 둬요.","(몇십)+(몇십)은 묶음끼리 더하고 0을 붙여요.","같은 자리끼리 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#1','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C1',1,'sa','auto','수 모형을 보세요. 52 + 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u6-C1","difficulty":1,"kind":"sa","stem":"수 모형을 보세요. 52 + 4 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_pair","left":{"tens":5,"ones":2},"right":{"tens":0,"ones":4},"op":"+"},"answer":["56"],"variant_rule":{"twodigit":{"op":"add","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 5 + 0 = 5, 낱개끼리 더하면 2 + 4 = 6이에요.","그래서 52 + 4 = 56이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#2','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C1',1,'mc','auto','50 + 30 은 얼마인가요?',ARRAY['M1-2-u6-X03','M1-2-u6-X01']::text[],true,'{"seq":2,"concept":"M1-2-u6-C1","difficulty":1,"kind":"mc","stem":"50 + 30 은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M1-2-u6-X03"},{"t":"53","mis":"M1-2-u6-X01"}],"variant_rule":{"twodigit":{"op":"add","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 더해요.","묶음 5 + 3 = 8 개 → 80이에요.","8은 0을 빠뜨린 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#3','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C1',3,'error','auto','보라가 52 + 4 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#4','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C2',1,'sa','auto','세로 셈을 보세요. 53 + 24 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u6-C2","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 53 + 24 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":53,"bottom":24,"op":"+","ans":null},"answer":["77"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 더하면 5 + 2 = 7, 낱개끼리 더하면 3 + 4 = 7이에요.","그래서 53 + 24 = 77이에요.","같은 자리끼리 더하고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#5','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C2',2,'mc','auto','35 + 41 에서 낱개 자리의 두 수를 더하면 얼마인가요?',ARRAY['M1-2-u6-X07']::text[],true,'{"seq":5,"concept":"M1-2-u6-C2","difficulty":2,"kind":"mc","stem":"35 + 41 에서 낱개 자리의 두 수를 더하면 얼마인가요?","asset":{"type":"vert","top":35,"bottom":41,"op":"+","ans":"hide"},"options":[{"t":"6","correct":true},{"t":"7","mis":"M1-2-u6-X07"},{"t":"76","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","ask":"ones"}},"explanation":["낱개 자리의 두 수는 5와 1이에요.","5 + 1 = 6이에요.","7은 묶음 자리를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
