INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#7','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C3',1,'mc','auto','파란 딱지 24개, 빨간 딱지 3개예요. 파란 딱지가 빨간 딱지보다 몇 개 더 많은지 구하는 식은 어느 것인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X04']::text[],false,'{"seq":7,"concept":"M1-2-u6-C3","difficulty":1,"kind":"mc","stem":"파란 딱지 24개, 빨간 딱지 3개예요. 파란 딱지가 빨간 딱지보다 몇 개 더 많은지 구하는 식은 어느 것인가요?","options":[{"t":"24 − 3","correct":true},{"t":"24 + 3","mis":"M1-2-u6-X05"},{"t":"3 − 24","mis":"M1-2-u6-X04"}],"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","큰 수 24에서 작은 수 3을 빼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#8','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C3',1,'sa','auto','90 − 40 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u6-C3","difficulty":1,"kind":"sa","stem":"90 − 40 은 얼마인가요? 10개씩 묶음끼리 빼서 숫자로 쓰세요.","answer":["50"],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["낱개가 없어요 — 묶음끼리만 빼요.","묶음 9개에서 4개를 빼면 묶음 5개 → 50이에요.","묶음 수 뒤에 0을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#9','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C3',2,'mc','auto','수 모형을 보세요. 66 − 4 는 얼마인가요?',ARRAY['M1-2-u6-X05','M1-2-u6-X07']::text[],true,'{"seq":9,"concept":"M1-2-u6-C3","difficulty":2,"kind":"mc","stem":"수 모형을 보세요. 66 − 4 는 얼마인가요?","asset":{"type":"bundle_pair","left":{"tens":6,"ones":6},"right":{"tens":0,"ones":4},"op":"-"},"options":[{"t":"62","correct":true},{"t":"70","mis":"M1-2-u6-X05"},{"t":"60","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+1","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 6 − 0 = 6, 낱개끼리 빼면 6 − 4 = 2예요.","그래서 66 − 4 = 62예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#10','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C4',1,'sa','auto','세로 셈을 보세요. 79 − 43 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u6-C4","difficulty":1,"kind":"sa","stem":"세로 셈을 보세요. 79 − 43 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"vert","top":79,"bottom":43,"op":"-","ans":null},"answer":["36"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 7 − 4 = 3, 낱개끼리 빼면 9 − 3 = 6이에요.","그래서 79 − 43 = 36이에요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#11','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C4',2,'mc','auto','97 − 53 는 얼마인가요?',ARRAY['M1-2-u6-X06','M1-2-u6-X07']::text[],true,'{"seq":11,"concept":"M1-2-u6-C4","difficulty":2,"kind":"mc","stem":"97 − 53 는 얼마인가요?","options":[{"t":"44","correct":true},{"t":"62","mis":"M1-2-u6-X06"},{"t":"40","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 9 − 5 = 4, 낱개끼리 빼면 7 − 3 = 4예요.","그래서 97 − 53 = 44예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
