INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#13','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C5',1,'sa','auto','약과 10개와 약과 45개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u6-C5","difficulty":1,"kind":"sa","stem":"약과 10개와 약과 45개를 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["약과","약과"],"ask":"story"}},"explanation":["「모두」는 모으는 이야기 — 덧셈이에요.","10 + 45 = 55예요.","묶음끼리, 낱개끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#14','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C5',2,'mc','auto','딱지 75개는 구슬 31개보다 몇 개 더 많은가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X07']::text[],true,'{"seq":14,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"딱지 75개는 구슬 31개보다 몇 개 더 많은가요?","options":[{"t":"44","correct":true},{"t":"106","mis":"M1-2-u6-X08"},{"t":"40","mis":"M1-2-u6-X07"}],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","items":["딱지","구슬"],"ask":"story"}},"explanation":["「몇 개 더 많은지」는 견주는 이야기 — 뺄셈이에요.","75 − 31 = 44예요.","106은 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#15','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C5',2,'mc','auto','「사탕 63개와 사탕 42개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?',ARRAY['M1-2-u6-X08','M1-2-u6-X04']::text[],true,'{"seq":15,"concept":"M1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「사탕 63개와 사탕 42개는 모두 몇 개일까요?」에 알맞은 식은 어느 것인가요?","options":[{"t":"63 + 42","correct":true},{"t":"63 − 42","mis":"M1-2-u6-X08"},{"t":"42 − 63","mis":"M1-2-u6-X04"}],"variant_rule":{"twodigit":{"op":"add","kind":"2+2","items":["사탕","사탕"],"ask":"expr"}},"explanation":["「모두」는 모으는 이야기예요.","모으는 이야기는 덧셈식으로 나타내요.","63 + 42 = 105예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#16','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C5',3,'error','auto','민수가 「딱지 75개가 구슬 31개보다 몇 개 더 많을까요?」를 이렇게 풀었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#17','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C6',1,'mc','auto','팽이 가운데 바르게 계산한 것은 어느 것인가요?',ARRAY['M1-2-u6-X10']::text[],true,'{"seq":17,"concept":"M1-2-u6-C6","difficulty":1,"kind":"mc","stem":"팽이 가운데 바르게 계산한 것은 어느 것인가요?","options":[{"t":"64 − 13 = 51","correct":true},{"t":"30 + 50 = 90","mis":"M1-2-u6-X10"},{"t":"26 − 10 = 6","mis":"M1-2-u6-X10"}],"variant_rule":{"twodigit":{"op":"mix","kind":"mix","ask":"check"}},"explanation":["64 − 13 = 51 는 맞아요.","나머지 둘은 직접 계산하면 답이 달라요.","하나씩 계산해 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#18','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C6',2,'sa','auto','팽이 「66 − 42 = 21」은 틀렸어요. 66 − 42 의 바른 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u6-C6","difficulty":2,"kind":"sa","stem":"팽이 「66 − 42 = 21」은 틀렸어요. 66 − 42 의 바른 답은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"variant_rule":{"twodigit":{"op":"sub","kind":"2+2","ask":"value"}},"explanation":["10개씩 묶음끼리 빼면 6 − 4 = 2, 낱개끼리 빼면 6 − 2 = 4예요.","그래서 66 − 42 = 24예요.","같은 자리끼리 빼고 그 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#19','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C6',2,'ox','auto','60 − 20 = 40 입니다.',ARRAY['M1-2-u6-X03']::text[],true,'{"seq":19,"concept":"M1-2-u6-C6","difficulty":2,"kind":"ox","stem":"60 − 20 = 40 입니다.","answer":"O","reason_options":[{"t":"묶음 6 − 2 = 4 이니까","correct":true},{"t":"6 − 2 = 4 이 답이니까","mis":"M1-2-u6-X03"}],"variant_rule":{"twodigit":{"op":"sub","kind":"tens","ask":"value"}},"explanation":["묶음 6개에서 2개를 빼면 4개예요.","묶음 4개는 40이에요 — 맞아요.","묶음 수 뒤에 0을 붙여 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#20','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C6',3,'error','auto','지우가 「57 − 41 = 16」 팽이를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#21','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C5',4,'essay','teacher','떡 그림(63개·42개·10개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M1-2-u6-C5","difficulty":4,"kind":"essay","stem":"떡 그림(63개·42개·10개)으로 덧셈 이야기 하나와 뺄셈 이야기 하나를 만들고, 각각 식과 답을 쓰세요.","answer_guide":"① 덧셈 이야기(모두) + 식·답(예: 63 + 42 = 105) ② 뺄셈 이야기(몇 개 더) + 식·답(예: 63 − 42 = 21) ③ 「모두」/「몇 개 더」 낱말 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["「모두 몇 개」 이야기는 덧셈 — 63 + 42 = 105.","「몇 개 더」 이야기는 뺄셈 — 63 − 42 = 21.","같은 그림으로 여러 이야기를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#22','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C2',4,'sa','auto','□ + 24 = 77 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M1-2-u6-C2","difficulty":4,"kind":"sa","stem":"□ + 24 = 77 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["53"],"explanation":["77은 묶음 7, 낱개 7이에요.","묶음 7 − 2 = 5, 낱개 7 − 4 = 3 — □는 53이에요.","53 + 24 = 77 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#23','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C4',4,'sa','auto','□ − 43 = 36 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M1-2-u6-C4","difficulty":4,"kind":"sa","stem":"□ − 43 = 36 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["79"],"explanation":["36에 뺀 43을 다시 더하면 처음 수예요.","36 + 43 = 79예요.","79 − 43 = 36 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#24','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C3',3,'ox','auto','66 − 4 와 4 − 66 은 답이 같습니다.',ARRAY['M1-2-u6-X04']::text[],false,'{"seq":24,"concept":"M1-2-u6-C3","difficulty":3,"kind":"ox","stem":"66 − 4 와 4 − 66 은 답이 같습니다.","answer":"X","reason_options":[{"t":"뺄셈은 큰 수에서 작은 수를 빼야 하니까","correct":true},{"t":"두 수만 같으면 되니까","mis":"M1-2-u6-X04"}],"explanation":["4에서 66을 뺄 수는 없어요.","견주는 뺄셈은 큰 수에서 작은 수를 빼요.","66 − 4 = 62예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u6_review_d#25','math',1,2,'u6','review','g1_2_math_u6_review_d','unit_review','M1-2-u6-C1',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u6-C1","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"52 + 4","r":"56"},{"l":"50 + 30","r":"80"},{"l":"66 − 4","r":"62"}],"explanation":["낱개끼리 더하거나 빼고 묶음은 그대로 둬요.","(몇십)+(몇십)은 묶음끼리 더하고 0을 붙여요.","같은 자리끼리 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
